import express from 'express'
const app = express()
app.use(express.json())

const books = [{ id: 1, title: 'Clean Code' }]

// chained: one path, many methods
app.route('/books')
  .get((req, res) => res.json(books))
  .post((req, res) => {
    const book = { id: books.length + 1, title: req.body.title }
    books.push(book)
    res.status(201).json(book)
  })

// all methods on a path
app.all('/ping', (req, res) => res.send(`pong via ${req.method}`))

// two handlers on one route
const logIt = (req, res, next) => { console.log('hit', req.originalUrl); next() }
app.get('/about', logIt, (req, res) => res.send('About page'))

app.listen(3000)

import express from 'express'
const app = express()

app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id)
  if (!Number.isInteger(id)) return res.status(400).json({ error: 'id must be a number' })
  res.json({ id, query: req.query })
})

app.get('/search', (req, res) => {
  const { q = '', page = '1', limit = '10' } = req.query
  res.json({ q, page: Number(page), limit: Number(limit) })
})

// optional param (Express 5 syntax)
app.get('/books{/:id}', (req, res) => {
  res.json({ id: req.params.id ?? null })
})

app.listen(3000)

