import express from 'express'
const app = express()

// named wildcard -> array
app.get('/files/*splat', (req, res) => {
  res.json({ path: req.params.splat.join('/') })
})

// optional segment
app.get('/books{/:id}', (req, res) => res.json({ id: req.params.id ?? 'all' }))

// RegExp path: anything ending with "fly"
app.get(/.*fly$/, (req, res) => res.send('ends with fly'))

// validate the param in code instead of inline regex
app.get('/orders/:id', (req, res, next) => {
  if (!/^\d+$/.test(req.params.id)) return next('route')
  res.json({ order: Number(req.params.id) })
})

// catch-all for unknown URLs (v5 syntax)
app.get('/{*splat}', (req, res) => res.status(404).send('no such page'))

app.listen(3000)

