import express, { Router } from 'express'
const app = express()

const comments = Router({ mergeParams: true })
comments.get('/', (req, res) => {
  res.json({ postId: req.params.postId, comments: [] })
})

const posts = Router()
posts.use('/:postId/comments', comments)

app.use('/posts', posts)
// GET /posts/5/comments -> {"postId":"5","comments":[]}

